From f0b75f88f0c5df48f7cb4108d03d3d4532b77839 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:49:12 +0100
Subject: [PATCH] applets/digital-clock: Follow the 12/24-hour setting in Copy
 to Clipboard

The Copy to Clipboard menu used the locale's time formats as they are,
so it offered AM/PM times while the clock was set to 24-hour time. Give
the menu the clock's own time formats, and convert to the clock's zone.

BUG: 452888
---
 applets/digital-clock/DigitalClock.qml        |  2 +
 .../digital-clock/plugin/clipboardmenu.cpp    | 43 +++++++++++++++----
 applets/digital-clock/plugin/clipboardmenu.h  | 13 ++++++
 3 files changed, 50 insertions(+), 8 deletions(-)

diff --git a/applets/digital-clock/DigitalClock.qml b/applets/digital-clock/DigitalClock.qml
index 8c918109d0..52255a8cc5 100644
--- a/applets/digital-clock/DigitalClock.qml
+++ b/applets/digital-clock/DigitalClock.qml
@@ -93,6 +93,8 @@ MouseArea {
         function onContextualActionsAboutToShow() {
             ClipboardMenu.secondsIncluded = (Plasmoid.configuration.showSeconds === 2);
             ClipboardMenu.timezone = clock.timeZone;
+            ClipboardMenu.timeFormat = main.timeFormat;
+            ClipboardMenu.timeFormatWithSeconds = main.timeFormatWithSeconds;
         }
     }

diff --git a/applets/digital-clock/plugin/clipboardmenu.cpp b/applets/digital-clock/plugin/clipboardmenu.cpp
index 8e2708252f..677bf5ab9d 100644
--- a/applets/digital-clock/plugin/clipboardmenu.cpp
+++ b/applets/digital-clock/plugin/clipboardmenu.cpp
@@ -45,6 +45,32 @@ void ClipboardMenu::setSecondsIncluded(bool secondsIncluded)
     }
 }

+QString ClipboardMenu::timeFormat() const
+{
+    return m_timeFormat;
+}
+
+void ClipboardMenu::setTimeFormat(const QString &timeFormat)
+{
+    if (m_timeFormat != timeFormat) {
+        m_timeFormat = timeFormat;
+        Q_EMIT timeFormatChanged();
+    }
+}
+
+QString ClipboardMenu::timeFormatWithSeconds() const
+{
+    return m_timeFormatWithSeconds;
+}
+
+void ClipboardMenu::setTimeFormatWithSeconds(const QString &timeFormatWithSeconds)
+{
+    if (m_timeFormatWithSeconds != timeFormatWithSeconds) {
+        m_timeFormatWithSeconds = timeFormatWithSeconds;
+        Q_EMIT timeFormatWithSecondsChanged();
+    }
+}
+
 void ClipboardMenu::setupMenu(QAction *action)
 {
     auto *menu = new QMenu;
@@ -53,7 +79,7 @@ void ClipboardMenu::setupMenu(QAction *action)
         menu->clear();
         QDateTime currentDateTime = QDateTime::currentDateTime();
         if (!m_timezone.isEmpty()) {
-            currentDateTime.setTimeZone(QTimeZone(m_timezone));
+            currentDateTime = currentDateTime.toTimeZone(QTimeZone(m_timezone));
         }
         if (!m_secondsIncluded) {
             QTime timeWithoutSeconds(currentDateTime.time().hour(), currentDateTime.time().minute(), 0);
@@ -64,17 +90,21 @@ void ClipboardMenu::setupMenu(QAction *action)
         const QTime time = currentDateTime.time();
         const QRegularExpression rx(QStringLiteral("[^0-9:]"));
         const QChar spaceCharacter = QLatin1Char(' ');
+        const QString shortTime = QLocale::system().toString(time, m_timeFormat);
+        // e.g. 12:30:01 PM Central European Standard Time
+        const QString longTime =
+            QLocale::system().toString(time, m_timeFormatWithSeconds) + spaceCharacter + QLocale::system().toString(currentDateTime, QStringLiteral("tttt"));
         QString timeString;
         QAction *menuOption;

         // e.g 12:30 PM or 12:30:01 PM
-        timeString = m_secondsIncluded ? QLocale::system().toString(time, QLocale::LongFormat) : QLocale::system().toString(time, QLocale::ShortFormat);
+        timeString = m_secondsIncluded ? longTime : shortTime;
         menuOption = menu->addAction(timeString);
         menuOption->setData(timeString);

         // the same as the option above but shows the opposite of the "show seconds" setting
         // e.g if "show seconds" is enabled it will show the time without seconds and vice-versa
-        timeString = m_secondsIncluded ? QLocale::system().toString(time, QLocale::ShortFormat) : QLocale::system().toString(time, QLocale::LongFormat);
+        timeString = m_secondsIncluded ? shortTime : longTime;
         menuOption = menu->addAction(timeString);
         menuOption->setData(timeString);

@@ -89,9 +119,7 @@ void ClipboardMenu::setupMenu(QAction *action)
         menuOption->setData(timeString);

         // e.g Thursday, April 28, 2022 12:30 PM or Thursday, April 28, 2022 12:30:01 PM -03
-        timeString = m_secondsIncluded
-            ? QLocale::system().toString(date, QLocale::LongFormat) + spaceCharacter + QLocale::system().toString(time, QLocale::LongFormat)
-            : QLocale::system().toString(date, QLocale::LongFormat) + spaceCharacter + QLocale::system().toString(time, QLocale::ShortFormat);
+        timeString = QLocale::system().toString(date, QLocale::LongFormat) + spaceCharacter + (m_secondsIncluded ? longTime : shortTime);
         menuOption = menu->addAction(timeString);
         menuOption->setData(timeString);

@@ -101,8 +129,7 @@ void ClipboardMenu::setupMenu(QAction *action)
         menuOption->setData(timeString);

         // e.g 2022-04-28 12:30 PM or 2022-04-28 12:30:01 PM -03
-        timeString = m_secondsIncluded ? date.toString(Qt::ISODate) + spaceCharacter + QLocale::system().toString(time, QLocale::LongFormat)
-                                       : date.toString(Qt::ISODate) + spaceCharacter + QLocale::system().toString(time, QLocale::ShortFormat);
+        timeString = date.toString(Qt::ISODate) + spaceCharacter + (m_secondsIncluded ? longTime : shortTime);
         menuOption = menu->addAction(timeString);
         menuOption->setData(timeString);

diff --git a/applets/digital-clock/plugin/clipboardmenu.h b/applets/digital-clock/plugin/clipboardmenu.h
index 8c33a0c0c4..2dcb9da047 100644
--- a/applets/digital-clock/plugin/clipboardmenu.h
+++ b/applets/digital-clock/plugin/clipboardmenu.h
@@ -20,6 +20,9 @@ class ClipboardMenu : public QObject
     // Holds the IANA timezone ID (e.g. "Europe/London")
     Q_PROPERTY(QByteArray timezone READ timezone WRITE setTimezone NOTIFY timezoneChanged)
     Q_PROPERTY(bool secondsIncluded READ secondsIncluded WRITE setSecondsIncluded NOTIFY secondsIncludedChanged)
+    // The time formats the clock itself uses, following its 12/24-hour setting
+    Q_PROPERTY(QString timeFormat READ timeFormat WRITE setTimeFormat NOTIFY timeFormatChanged)
+    Q_PROPERTY(QString timeFormatWithSeconds READ timeFormatWithSeconds WRITE setTimeFormatWithSeconds NOTIFY timeFormatWithSecondsChanged)

 public:
     explicit ClipboardMenu(QObject *parent = nullptr);
@@ -31,13 +34,23 @@ public:
     bool secondsIncluded() const;
     void setSecondsIncluded(bool secondsIncluded);

+    QString timeFormat() const;
+    void setTimeFormat(const QString &timeFormat);
+
+    QString timeFormatWithSeconds() const;
+    void setTimeFormatWithSeconds(const QString &timeFormatWithSeconds);
+
     Q_INVOKABLE void setupMenu(QAction *action);

 Q_SIGNALS:
     void timezoneChanged();
     void secondsIncludedChanged();
+    void timeFormatChanged();
+    void timeFormatWithSecondsChanged();

 private:
     QByteArray m_timezone;
     bool m_secondsIncluded = false;
+    QString m_timeFormat;
+    QString m_timeFormatWithSeconds;
 };
-- 
